{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In rats, compound 1a achieved a brain/plasma Kp of 3.4 after IV dosing, directly demonstrating meaningful CNS access; this high-transfer result supports a pass prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A 125I-labeled piperazine analogue showed a brain-to-blood ratio >20:1 in rats, indicating robust brain uptake and supporting the query's CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "PRE-084 distributed rapidly to mouse CNS with brain concentrations (773.6 ng/g) exceeding plasma at Tmax, supporting meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The blebbistatin analog NMIIi2 had a brain/plasma Kp of 2.32 in mice, confirming BBB crossing and supporting a pass prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Viloxazine was detected in human CSF with sustained concentrations over 10 hours, providing direct human evidence of BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Reserpine rapidly entered rabbit brain after IV administration, demonstrating that a lipophilic fused-heterocycle can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In control rats, irinotecan brain interstitium levels were <1% of plasma, indicating poor CNS penetration in the absence of BBB disruption; this contradictory record is outweighed by the query's more CNS-like physicochemical features and the preponderance of positive high-transfer evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: multiple high-transfer direct CNS exposure measurements (Kp 2.3-3.4, brain-to-blood >20, brain > plasma, human CSF detection) indicate meaningful BBB access; the single negative irinotecan microdialysis record is structurally less applicable and outweighed.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query molecule itself.",
    "Unbound brain concentrations and P-gp/BCRP efflux status for the query are not directly reported.",
    "The contradictory irinotecan record reflects a much more polar prodrug and may not capture the query's passive permeability/efflux profile."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

